<style>
.cash-page{color:#172033}.cash-page>header{display:flex;justify-content:space-between;align-items:end;margin-bottom:22px}.cash-page>header span{text-transform:uppercase;letter-spacing:.12em;font-size:11px;font-weight:800;color:#798880}.cash-page h1{font:700 32px/1.1 Georgia,serif;margin:4px 0}.cash-page header p{margin:0;color:#7f8b9b}.cash-primary{display:inline-flex;align-items:center;justify-content:center;gap:8px;background:#176656!important;color:#fff!important;border:0;border-radius:12px;padding:12px 17px;text-decoration:none;font-weight:750}.cash-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:13px;margin-bottom:17px}.cash-metrics>div{display:flex;align-items:center;gap:12px;background:#fff;border:1px solid #e0e7e2;border-radius:17px;padding:16px}.cash-metrics i{display:grid;place-items:center;width:42px;height:42px;border-radius:12px;background:#e7f5f1;color:#176656;font-size:20px}.cash-metrics small,.cash-metrics strong{display:block}.cash-metrics small{color:#8591a0}.cash-table{background:#fff;border:1px solid #e0e7e2;border-radius:19px;overflow:auto}.cash-table table{width:100%;border-collapse:collapse}.cash-table th{padding:12px 16px;background:#f7f9f8;text-align:left;color:#7e8b84;text-transform:uppercase;font-size:10px}.cash-table td{padding:15px 16px;border-top:1px solid #ebefec}.cash-table td strong,.cash-table td small{display:block}.cash-table td small{color:#8692a0}.cash-table td>span{background:#fff4d9;color:#986700;padding:5px 8px;border-radius:12px;font-size:11px}.cash-action{color:#176656;text-decoration:none;font-weight:750}.cash-table>footer{padding:14px}.cash-overlay{display:none;position:fixed;inset:0;z-index:1100;place-items:center;padding:20px}.cash-overlay:target{display:grid}.cash-backdrop{position:absolute;inset:0;background:rgba(18,29,43,.7);backdrop-filter:blur(3px)}.cash-overlay>section{position:relative;width:min(720px,95vw);background:#fff;border-radius:22px;overflow:hidden}.cash-overlay section>header{display:flex;justify-content:space-between;padding:20px 24px;border-bottom:1px solid #e4eae6}.cash-overlay h2{margin:0}.cash-overlay header p{margin:3px 0;color:#84909f}.cash-overlay header>a{font-size:25px;color:#7d8998}.cash-overlay form{display:grid;grid-template-columns:1fr 1fr;gap:16px;padding:23px}.cash-overlay form label:first-child{grid-column:1/-1}.cash-overlay label{font-weight:700;color:#4c5b52}.cash-overlay input,.cash-overlay select{display:block;width:100%;border:1px solid #d8e1da;border-radius:12px;padding:12px;margin-top:6px;background:#fff}.cash-overlay label small{display:block;color:#8894a2;font-weight:400;margin-top:5px}.cash-overlay section>footer{display:flex;justify-content:flex-end;gap:10px;padding:14px 23px;border-top:1px solid #e4eae6}.cash-overlay footer>a{padding:11px 17px;border:1px solid #dce4df;border-radius:11px;color:#344557;text-decoration:none}@media(max-width:800px){.cash-metrics{grid-template-columns:1fr 1fr}.cash-page>header{align-items:flex-start;flex-direction:column;gap:13px}.cash-overlay form{grid-template-columns:1fr}.cash-overlay form label:first-child{grid-column:auto}}
</style>
